INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('40807644-4c1a-5a94-9487-e78dee955076','TEXT','The Paper Kite Map','Luca liked helping at the open oval, especially when there was a small job that nobody had planned. One Friday, Luca noticed the kite map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
