INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('92f05c7e-36e7-541c-9a9f-a9188dfa894e','TEXT','The Museum Window','Eli liked helping at the local museum, especially when there was a small job that nobody had planned. One Saturday, Eli noticed the old window frame was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Eli decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('a653f218-59e4-5237-b996-06535bf45c10','TEXT','The Tiny Ferry — A Different Day','Amara liked helping at the river workshop, especially when there was a small job that nobody had planned. One Saturday, Amara noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
