INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('25636859-89a3-5145-b1a7-ede403446f08','TEXT','The Tiny Ferry','Amara liked helping at the river workshop, especially when there was a small job that nobody had planned. One Friday, Amara noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Amara decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('20220af2-4205-5579-8479-0e1ac2ac1b0a','TEXT','The Bicycle Bell Project — A Different Day','Kai liked helping at the bike path, especially when there was a small job that nobody had planned. One Tuesday, Kai noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Kai decided to stop and look carefully instead of rushing.
