INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('bdbe6e86-85d4-5b9c-acf6-c44a23c82e4f','TEXT','The Repaired Book','Sienna liked helping at the library corner, especially when there was a small job that nobody had planned. One Saturday, Sienna noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Sienna decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('9237ff62-f6b6-58de-a4a1-ec79e41c151c','TEXT','The Windy Sculpture — A Different Day','Noah liked helping at the community hall, especially when there was a small job that nobody had planned. One Thursday, Noah noticed the reed sculpture was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
